insert into public.site_settings (id, site_title, meta_description, footer_note, show_assistant)
values (1, 'Pushkar Panwar — Full-Stack & Applied AI Developer', 'Pushkar Panwar is a full-stack and applied AI developer from New Delhi building RAG, LLM and voice-powered web apps. Explore projects, skills and hackathon builds — or ask Mikuro, the portfolio cat.', 'Sketching my way with code from New Delhi. Built with Next.js and one very opinionated chrome cat.', true)
