insert into public.profiles (id, name, designation, introduction, description, location, availability, profile_image_url, cta_primary_label, cta_primary_href, cta_secondary_label, cta_secondary_href, stats)
values (1, 'Pushkar Panwar', 'Full-Stack & Applied AI Developer', 'Sketching my way with code: I build things that listen, read and talk back.', 'I build web products with an AI core: RAG and LLM apps, streaming chat and voice interfaces, and practical tools that solve one clear problem. Right now that means Octova, a Hinglish-first AI captioning tool for Indian creators, alongside a steady run of hackathon builds and Next.js experiments, from the first problem sketch to the deployed product.', 'New Delhi, India', 'Open to internships, freelance builds and hackathon teams', '/placeholders/profile.svg', 'See my work', '#work', 'Get in touch', '#contact', '[{"value":"1,830","label":"GitHub contributions in the last year"},{"value":"45","label":"public repositories on GitHub"},{"value":"134","label":"LeetCode problems solved"},{"value":"3","label":"hackathons in one season"}]'::jsonb)
on conflict (id) do update set name = excluded.name, designation = excluded.designation, introduction = excluded.introduction, description = excluded.description, location = excluded.location, availability = excluded.availability, profile_image_url = excluded.profile_image_url, cta_primary_label = excluded.cta_primary_label, cta_primary_href = excluded.cta_primary_href, cta_secondary_label = excluded.cta_secondary_label, cta_secondary_href = excluded.cta_secondary_href, stats = excluded.stats;
insert into public.about_content (id, headline, introduction, biography, background, interests, highlights, image_url)
values (1, 'AI student, hackathon regular, always shipping something.', 'Hi, I''m Pushkar: an AI student and pre-founder from New Delhi. I build things that listen, read and talk back, and I care about the gap between a clever demo and something a person actually enjoys using.', 'My current orbit is full-stack development, Python, SQL and applied AI/ML, from the first problem sketch to the interface and the working product. I learn quickly, build for people, and iterate until the details land.

The main build right now is Octova, an AI caption tool for the Hinglish internet, built on free tiers. Around it runs a steady stream of hackathons and side projects: KhetKaaj at HackIIITD, KrishiSetu AI for the Smart India Hackathon and The Equal Pour at ForkIT, plus AI tools like BreakDSA, Versus and IGRIS Voice.', 'Undergraduate at K.R. Mangalam University. Generative AI internship with Prodigy InfoTech (GPT-2 fine-tuning, Stable Diffusion, Markov chains and neural style transfer), and the JPMorgan Chase Advanced Software Engineering job simulation on Forage.', array['Applied AI & RAG', 'LLM products', 'Voice interfaces', 'Computer vision', 'Hackathons', 'Building for the Hinglish internet']::text[], '[{"title":"Google · Gemini Ambassador","description":"Part of Google''s Gemini Ambassador program."},{"title":"Microsoft · Student Ambassador","description":"Member of the Microsoft Student Ambassadors community."},{"title":"GSSoC ’26 Contributor","description":"Open-source contributor in GirlScript Summer of Code 2026."},{"title":"Three hacks, one season","description":"Smart India Hackathon (KrishiSetu AI), HackIIITD (KhetKaaj) and ForkIT (The Equal Pour, 24 hours)."},{"title":"LeetCode · 134 solved","description":"63 easy, 50 medium and 21 hard problems, mostly in Python. 50 Days Badge 2026."},{"title":"Community","description":"TRYST, IIT Delhi and Mediaverse."}]'::jsonb, '/placeholders/about.svg')
on conflict (id) do update set headline = excluded.headline, introduction = excluded.introduction, biography = excluded.biography, background = excluded.background, interests = excluded.interests, highlights = excluded.highlights, image_url = excluded.image_url;
insert into public.contact_details (id, email, phone, location, availability_note, socials, form_enabled)
values (1, 'pushkarpanwar0001@gmail.com', '', 'New Delhi, India', 'Open to internships, freelance builds, hackathon teams and interesting ideas. The quickest way is a message here or on LinkedIn.', '[{"platform":"github","label":"GitHub","url":"https://github.com/TheVoidJulius"},{"platform":"linkedin","label":"LinkedIn","url":"https://www.linkedin.com/in/pushkar-panwar-1b7690381"},{"platform":"other","label":"LeetCode","url":"https://leetcode.com/u/pushkar02panwar/"},{"platform":"x","label":"X / Twitter","url":"https://x.com/Pushkar3lg"},{"platform":"instagram","label":"Instagram","url":"https://www.instagram.com/fwpushkar"}]'::jsonb, true)
