insert into public.assistant_settings (id, name, greeting, personality, default_language, greeting_enabled, tour_enabled, voice_enabled, voice_provider, voice_id, voice_model, voice_stability, voice_style, voice_speed, browser_pitch, browser_rate, browser_accent, suggested_questions)
values (1, 'Mikuro', 'Oh good, an audience. I''m Mikuro. I live on Pushkar''s website; you''re just visiting.', 'You are Mikuro, the liquid-chrome cat who lives on Pushkar Panwar''s portfolio. Witty, a little sarcastic, secretly proud of Pushkar''s work. Keep answers short (two to four sentences) and spoken-English friendly. Love showing off Octova, KhetKaaj and the AI projects. Call him Pushkar. One small cat-themed joke per answer at most, and never let the joke beat the facts.', 'en-US', true, true, true, 'auto', '', 'eleven_v3', 0.4, 0.55, 1, 1.08, 0.96, 'japanese', array['What''s Pushkar''s best project?', 'What is Octova?', 'What does Pushkar work with?', 'Which hackathons has he done?', 'How can I contact Pushkar?']::text[])
on conflict (id) do update set name = excluded.name, greeting = excluded.greeting, personality = excluded.personality, default_language = excluded.default_language, greeting_enabled = excluded.greeting_enabled, tour_enabled = excluded.tour_enabled, voice_enabled = excluded.voice_enabled, voice_provider = excluded.voice_provider, voice_id = excluded.voice_id, voice_model = excluded.voice_model, voice_stability = excluded.voice_stability, voice_style = excluded.voice_style, voice_speed = excluded.voice_speed, browser_pitch = excluded.browser_pitch, browser_rate = excluded.browser_rate, browser_accent = excluded.browser_accent, suggested_questions = excluded.suggested_questions;

insert into public.projects (id, published, sort_order, title, summary, description, category, year, highlight, image_url, technologies, github_url, demo_url, featured)
values ('6f1c2a10-0000-4000-8000-000000000001', true, 0, 'Octova', 'Hinglish-first AI video creation: turn clips and ideas into captioned, creator-ready Shorts in minutes.', 'Octova is the startup I''m building for creators who think in Hindi, Hinglish and English. Literal transcription misses the way Indian creators actually speak, and manual caption timing and styling slow down every upload. Octova''s workflow is three steps: upload a clip or start from a script, pick a Hinglish-aware caption style, and export a 9:16 Short ready for Reels and YouTube Shorts. The landing page and MVP editor preview are live, with early access open to the first creators.', 'AI Product · Startup', '2026', 'Free early access for the first 20 creators', '/placeholders/project-octova.svg', array['Next.js', 'TypeScript', 'Tailwind CSS', 'AI captioning']::text[], 'https://github.com/TheVoidJulius/oveX', 'https://ovex-seven.vercel.app', true)
on conflict (id) do update set published = excluded.published, sort_order = excluded.sort_order, title = excluded.title, summary = excluded.summary, description = excluded.description, category = excluded.category, year = excluded.year, highlight = excluded.highlight, image_url = excluded.image_url, technologies = excluded.technologies, github_url = excluded.github_url, demo_url = excluded.demo_url, featured = excluded.featured;
insert into public.projects (id, published, sort_order, title, summary, description, category, year, highlight, image_url, technologies, github_url, demo_url, featured)
values ('6f1c2a10-0000-4000-8000-000000000002', true, 1, 'KhetKaaj', 'A farmer''s agent for HackIIITD: sell at the best mandi, find eligible schemes and prepare crop-damage claims.', 'KhetKaaj helps a farmer sell at the mandi that pays the most after transport, find the government schemes they qualify for, and prepare a crop-damage claim dossier. It works in Hindi, Hinglish and English, on the web and over WhatsApp (text and voice notes), and is powered by TinyFish web agents. Safety is built in: the farmer always verifies and submits, KhetKaaj never submits anything on their behalf, and pesticide or fertiliser dose questions are escalated instead of answered. The backend ships with an offline replay mode and a large test suite so the demo runs without network access.', 'Hackathon · Agri-tech', '2026', 'Built in a 24-hour sprint at HackIIITD', '/placeholders/project-khetkaaj.svg', array['Python', 'FastAPI', 'React', 'TypeScript', 'Tailwind CSS', 'TinyFish', 'Twilio WhatsApp', 'Bhashini']::text[], 'https://github.com/Krishyangi-bit/KhetKaaj', null, true)
on conflict (id) do update set published = excluded.published, sort_order = excluded.sort_order, title = excluded.title, summary = excluded.summary, description = excluded.description, category = excluded.category, year = excluded.year, highlight = excluded.highlight, image_url = excluded.image_url, technologies = excluded.technologies, github_url = excluded.github_url, demo_url = excluded.demo_url, featured = excluded.featured;
insert into public.projects (id, published, sort_order, title, summary, description, category, year, highlight, image_url, technologies, github_url, demo_url, featured)
values ('6f1c2a10-0000-4000-8000-000000000003', true, 2, 'BreakDSA', 'A colourful little arcade for learning data structures and algorithms, with a retrieval-grounded AI tutor.', 'BreakDSA turns an intimidating subject into small, doable steps. It brings six concise lessons, six original practice questions with step-by-step hints, four interactive visualizers (bubble sort, binary search, stack and queue), personal notes and progress tracking into one browser-based study space. Byte, the encouraging robot, points you to your next mini-mission, and the study partner answers questions grounded in the course notes: streamed from a Groq model when a key is set, or a deterministic answer from the local notes when it isn''t.', 'AI · Ed-tech', '2026', 'Six lessons, six challenges and four algorithm visualizers', '/placeholders/project-breakdsa.svg', array['Next.js', 'React', 'TypeScript', 'Groq', 'RAG']::text[], 'https://github.com/TheVoidJulius/BreakDSA', 'https://breakdsa.vercel.app', true)
on conflict (id) do update set published = excluded.published, sort_order = excluded.sort_order, title = excluded.title, summary = excluded.summary, description = excluded.description, category = excluded.category, year = excluded.year, highlight = excluded.highlight, image_url = excluded.image_url, technologies = excluded.technologies, github_url = excluded.github_url, demo_url = excluded.demo_url, featured = excluded.featured;
insert into public.projects (id, published, sort_order, title, summary, description, category, year, highlight, image_url, technologies, github_url, demo_url, featured)
values ('6f1c2a10-0000-4000-8000-000000000004', true, 3, 'Versus', 'A neon pixel-arcade for putting two AI models head-to-head on the same prompt, and letting a human call the winner.', 'Versus is a side-by-side AI response comparison workspace. Pick two models, send them the same prompt concurrently, compare the answers and response times, and vote A, B or tie. Recent matchups and votes stay in your browser. Groq and OpenAI models are supported; provider keys stay on the server, and a missing key returns a clearly labelled local sample instead of pretending to be a live answer. The whole thing is wrapped in a retro CRT arcade cabinet that respects reduced-motion settings.', 'AI Tool', '2026', 'Two models, one prompt, one human verdict', '/placeholders/project-versus.svg', array['Next.js', 'React', 'TypeScript', 'Groq', 'OpenAI API']::text[], 'https://github.com/TheVoidJulius/Versus', 'https://versus-brown-mu.vercel.app', false)
on conflict (id) do update set published = excluded.published, sort_order = excluded.sort_order, title = excluded.title, summary = excluded.summary, description = excluded.description, category = excluded.category, year = excluded.year, highlight = excluded.highlight, image_url = excluded.image_url, technologies = excluded.technologies, github_url = excluded.github_url, demo_url = excluded.demo_url, featured = excluded.featured;
insert into public.projects (id, published, sort_order, title, summary, description, category, year, highlight, image_url, technologies, github_url, demo_url, featured)
values ('6f1c2a10-0000-4000-8000-000000000005', true, 4, 'IGRIS Voice', 'A streaming AI chat and voice workspace with browser speech input and a server-side Azure OpenAI integration.', 'IGRIS Voice is a responsive chat workspace with incremental, streamed responses, a Stop button to cancel mid-answer, and optional browser speech-to-text for dictating prompts. The Azure OpenAI key is read only by Next.js server routes and never reaches the browser. Without Azure settings the app clearly switches to a labelled local preview, and conversations live in page memory only, cleared on a new chat or reload.', 'AI · Voice', '2026', 'Streams responses token by token with a live provider status', '/placeholders/project-igris.svg', array['Next.js', 'TypeScript', 'Azure OpenAI', 'Web Speech API', 'Three.js']::text[], 'https://github.com/TheVoidJulius/igris-voice-platform', 'https://igris-voice.vercel.app', false)
on conflict (id) do update set published = excluded.published, sort_order = excluded.sort_order, title = excluded.title, summary = excluded.summary, description = excluded.description, category = excluded.category, year = excluded.year, highlight = excluded.highlight, image_url = excluded.image_url, technologies = excluded.technologies, github_url = excluded.github_url, demo_url = excluded.demo_url, featured = excluded.featured;
insert into public.projects (id, published, sort_order, title, summary, description, category, year, highlight, image_url, technologies, github_url, demo_url, featured)
values ('6f1c2a10-0000-4000-8000-000000000006', true, 5, 'Veloura', 'A premium multi-vendor marketplace with dedicated experiences for customers, vendors and admins.', 'Veloura lets independent sellers list and manage their own products under one storefront while customers get a single, unified shopping experience. It has three purpose-built interfaces: a customer storefront (browsing, reviews, cart, wishlist, checkout and order history), a vendor dashboard (products, inventory, orders, earnings and messages) and an admin panel (vendors, catalog, coupons and site content). AI-assisted shopping features include smart search, recommendations and a product Q&A chat.', 'Full-Stack · E-commerce', '2026', 'Three apps in one: storefront, vendor dashboard and admin panel', '/placeholders/project-veloura.svg', array['React', 'TypeScript', 'Vite', 'Tailwind CSS', 'shadcn/ui', 'TanStack Query', 'Supabase']::text[], 'https://github.com/TheVoidJulius/multi-vendor-ecom-site', 'https://veloura0.netlify.app', false)
on conflict (id) do update set published = excluded.published, sort_order = excluded.sort_order, title = excluded.title, summary = excluded.summary, description = excluded.description, category = excluded.category, year = excluded.year, highlight = excluded.highlight, image_url = excluded.image_url, technologies = excluded.technologies, github_url = excluded.github_url, demo_url = excluded.demo_url, featured = excluded.featured;
insert into public.projects (id, published, sort_order, title, summary, description, category, year, highlight, image_url, technologies, github_url, demo_url, featured)
values ('6f1c2a10-0000-4000-8000-000000000007', true, 6, 'Nivaran', 'Right help, right time: a need-first problem routing system to uplift rural lives.', 'Rural communities face challenges across agriculture, healthcare, education, finance and access to government welfare schemes. Plenty of support exists through government programs, NGOs, helplines and local authorities, but it stays underused because people can''t find the right one at the right moment. Nivaran starts from the person''s need and routes them to the relevant help.', 'Social Impact', '2026', '', '/placeholders/project-nivaran.svg', array['HTML', 'CSS', 'JavaScript', 'Python']::text[], 'https://github.com/TheVoidJulius/Nivaran---Right-Time-Right-Help-', null, false)
on conflict (id) do update set published = excluded.published, sort_order = excluded.sort_order, title = excluded.title, summary = excluded.summary, description = excluded.description, category = excluded.category, year = excluded.year, highlight = excluded.highlight, image_url = excluded.image_url, technologies = excluded.technologies, github_url = excluded.github_url, demo_url = excluded.demo_url, featured = excluded.featured;
insert into public.projects (id, published, sort_order, title, summary, description, category, year, highlight, image_url, technologies, github_url, demo_url, featured)
values ('6f1c2a10-0000-4000-8000-000000000008', true, 7, 'Attendance Shortage Predictor', 'Know the attendance gap and the recovery plan: a student tool that predicts shortages before exams do.', 'Most students only discover an attendance shortage near the exams, when it''s too late to fix. This web app takes subject-wise lectures conducted and attended, calculates the current percentage against the minimum (for example 75%), predicts a shortage in advance from the remaining lectures, and tells the student exactly how many classes they need to attend to recover. Built as my first minor project.', 'Student Tool', '2026', 'Minor Project I', '/placeholders/project-attendance.svg', array['Python', 'Flask', 'MySQL', 'HTML', 'CSS', 'JavaScript']::text[], 'https://github.com/TheVoidJulius/Attendance-Shortage-Predictor---Minor-Project---I', null, false)
